<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php'; require_role(['admin','staff']); verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $cid=(int)($_POST['customer_id']??0);$period=trim($_POST['billing_period']??'');$reading=(float)($_POST['reading_value']??-1);$date=$_POST['reading_date']??date('Y-m-d');$notes=trim($_POST['notes']??'');
 $s=$pdo->prepare("SELECT id,previous_reading FROM customers WHERE id=? AND status='active'");$s->execute([$cid]);$c=$s->fetch();
 if(!$c||!preg_match('/^\d{4}-\d{2}$/',$period)||$reading<0){flash('error','Enter a valid customer, billing period and non-negative reading.');redirect('readings.php');}
 $prev=(float)$c['previous_reading'];
 if($reading<$prev){flash('error','New meter reading cannot be lower than the previous reading.');redirect('readings.php');}
 try{$s=$pdo->prepare("INSERT INTO meter_readings(customer_id,billing_period,previous_reading,reading_value,consumption,reading_date,recorded_by,notes) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$cid,$period,$prev,$reading,$reading-$prev,$date,current_user()['id'],$notes]);$pdo->prepare("UPDATE customers SET previous_reading=? WHERE id=?")->execute([$reading,$cid]);audit($pdo,'ADD METER READING',"Customer #$cid, period $period");flash('success','Meter reading recorded. Consumption: '.number_format($reading-$prev,2).' m³.');}
 catch(PDOException $e){flash('error','A reading already exists for this customer and billing period, or the record could not be saved.');}
 redirect('readings.php');
}
$customers=$pdo->query("SELECT id,account_number,full_name,meter_number,previous_reading FROM customers WHERE status='active' ORDER BY full_name")->fetchAll();
$rows=$pdo->query("SELECT r.*,c.full_name,c.account_number,u.name AS staff_name FROM meter_readings r JOIN customers c ON c.id=r.customer_id LEFT JOIN users u ON u.id=r.recorded_by ORDER BY r.created_at DESC LIMIT 100")->fetchAll();$pageTitle='Meter readings';require 'includes/header.php';
?>
<div class="two-col"><div class="panel"><div class="panel-head"><h3>Capture meter reading</h3></div><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Customer *</label><select name="customer_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['account_number'].' · '.$c['full_name'].' · '.$c['meter_number'].' (previous: '.$c['previous_reading'].' m³)')?></option><?php endforeach;?></select><label>Billing period *</label><input type="month" name="billing_period" value="<?=date('Y-m')?>" required><label>Current meter reading (m³) *</label><input type="number" name="reading_value" min="0" step="0.01" required><label>Reading date</label><input type="date" name="reading_date" value="<?=date('Y-m-d')?>" required><label>Notes</label><textarea name="notes" rows="3" placeholder="Optional observations"></textarea><button class="btn primary">Save reading</button><p class="hint">The system calculates consumption by subtracting the customer's previous reading. One reading per customer per billing period is allowed.</p></form></div>
<div class="panel"><h3>Reading rules</h3><ul class="feature-list"><li>Readings must be zero or greater.</li><li>A new reading cannot be lower than the previous reading.</li><li>Duplicate readings for the same billing period are rejected.</li><li>Consumption = current reading − previous reading.</li><li>Readings update the customer's latest meter value.</li></ul><div class="note-box">Confirm the physical meter value before saving. A saved reading is used as the basis for billing.</div></div></div>
<div class="panel"><div class="panel-head"><h3>Recent meter readings</h3><input class="search-input" data-table-search="readings-table" placeholder="Search readings..."></div><div class="table-wrap"><table id="readings-table"><thead><tr><th>Customer</th><th>Period</th><th>Previous</th><th>Current</th><th>Consumption</th><th>Date</th><th>Recorded by</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><small class="table-sub"><?=e($r['account_number'])?></small></td><td><?=e($r['billing_period'])?></td><td><?=number_format($r['previous_reading'],2)?></td><td><?=number_format($r['reading_value'],2)?></td><td><b><?=number_format($r['consumption'],2)?> m³</b></td><td><?=e($r['reading_date'])?></td><td><?=e($r['staff_name']??'—')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty">No readings recorded yet.</td></tr><?php endif;?></tbody></table></div></div>
<?php require 'includes/footer.php';?>
